import {parameterNotes,colorNames} from './model-notes.mjs?v=20261101-lite1';
import {mean,finite,esc,csv,parseCSV,normalizeRows,validateRows,selectUsableRows,recordIdentity,splitData,ruleScan,classifyWell,fieldInfo,features,regressionMetrics} from './core.mjs?v=20261101-lite1';
import {MODELS,trainModel,predictModel,evaluate,exportFit,inferenceRequired} from './models.mjs?v=20261101-lite1';
const $=s=>document.querySelector(s), root=$('#app');
const states=Object.fromEntries(MODELS.map(m=>[m.id,{data:{train:[],val:[],test:[],all:[],calc:[]},fit:null,results:[],metrics:{},history:[],busy:false,tab:'data',role:'test'}]));
let catalog=[];
let page='overview',modelId='stgnn',data=[],well='all',experiments=[],alerts=[],answer='',source='Volve公开实测生产资料',overlay=false;
const titles={overview:'生产态势总览',models:'模型实验工作台',alerts:'异常预警与诊断',agent:'生产研判智能体',data:'数据与特征中心',experiments:'实验记录与反馈'};
const num=(n,d=1)=>Number.isFinite(Number(n))&&n!==null&&n!==''?Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d}):'—';
const fmt=(n,d=3)=>n===null||n===undefined?'—':num(n,d);
const metricName={MAE:'平均绝对误差',RMSE:'均方根误差',R2:'决定系数',MAPE:'百分比误差',Accuracy:'准确率',Precision:'精确率',Recall:'召回率',F1:'F1分数',FPR:'误报率',N:'评价样本数',UnknownTrueCount:'训练未见真实类别数'};
const current=()=>states[modelId],spec=()=>MODELS.find(m=>m.id===modelId);
const scoped=()=>well==='all'?data:data.filter(r=>r.well_id===well);
const wells=()=>[...new Set(data.map(r=>r.well_id))];
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),5500);}
function save(name,body,type='text/csv;charset=utf-8'){const b=body instanceof Blob?body:new Blob([body],{type});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function defaultDataset(id=modelId){return id==='event3w'?'threew':id==='esp'?'esp':id==='horner'||id==='pinn'?'dst':id==='tracer'?'tracer':'volve';}
const eventNames=['正常运行','含水及沉积物比例突增','井下安全阀异常关闭','严重段塞流','流动不稳定','产能快速损失','节流阀快速受限','节流阀结垢','生产管线水合物','服务管线水合物'];
const faultNames={'Normal':'正常','Unbalance':'不平衡','Faulty sensor':'传感器故障','Rubbing':'摩擦','Misalignment':'不对中'};
function labelNote(v,id=modelId){if(v===null||v===undefined)return '未覆盖';if(id==='event3w')return `${v}（${eventNames[Number(v)]??'未知事件'}）`;if(id==='esp')return `${v}（${faultNames[v]??'原始类别'}）`;return String(v);}
function warningLegend(){return `<div class="warning-legend" aria-label="预警颜色注释"><span><i class="severity red"></i><b>红色 · 优先核查</b> 持续明显异常或多信号组合</span><span><i class="severity yellow"></i><b>黄色 · 关注复核</b> 单项越限或趋势变化</span><span><i class="severity blue"></i><b>蓝色 · 跟踪观察</b> 工况变化线索</span><span><i class="severity green"></i><b>绿色 · 未命中所选规则</b> 不代表已证明无故障</span><span><i class="severity gray"></i><b>灰色 · 未覆盖 / 资料不足</b> 不生成虚构结果</span></div>`;}
function datasetChoice(m,s){const id=s.datasetId??defaultDataset(m.id);return `<div class="row dataset-choice"><label class="input-label">真实资料与对应模型<select id="model-dataset">${catalog.filter(d=>d.models.includes(m.id)).map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${esc(d.title)}${d.available?'':' · 待上传'}</option>`).join('')}</select></label><small class="muted">轻量样本按需加载，建议10轮先跑通流程；实际耗时依设备记录。完整资料与来源见数据中心。</small></div>`;}
function coverageBox(s){const parametric=['arps','crm','horner','tracer'].includes(modelId);const expected=[...s.data.val,...s.data.test];if(!s.data.train.length)return '';const key=r=>r.test_id??r.well_id??'未命名';const trained=new Set(s.data.train.map(key)),missing=[...new Set(expected.map(key))].filter(k=>!trained.has(k));return `<div class="notice ${missing.length?'error':''}"><b>训练覆盖检查：</b>训练集覆盖${trained.size}个井/测试对象。${missing.length?(parametric?'验证/测试中未覆盖：'+missing.map(esc).join('、')+'。逐井参数模型建议改选“逐井按时间”；未覆盖对象会留空并标记，不中断其他对象。':'有'+missing.length+'个监测对象未见于训练集；共享特征模型可进行推理，应额外核验跨对象泛化效果。'):'验证/测试对象均出现在训练资料中。'}${s.split?.method==='well-time'?'<br>逐井时间切分保留各井历史，避免F-5等晚投产井只进入测试集；各井截止日期不同，不等同于统一未来时点评估。':''}</div>`;}
function catalogPanel(){return `<section class="panel gap"><div class="panel-head"><h2>全部资料与对应模型</h2><span class="tag">4套轻量实测 · 1套待上传 · ${MODELS.length}模型</span></div><div class="panel-body"><div class="dataset-cards">${catalog.map(d=>`<article class="dataset-card"><div class="row" style="justify-content:space-between"><h3>${esc(d.title)}</h3><span class="tag ${d.available?'green':''}">${d.available?num(d.count,0)+'条':'待上传原始实测'}</span></div><p class="desc">${esc(d.description)}</p>${d.sample_path?`<div class="notice"><b>轻量实测：${d.sample_count}行 · ${d.sample_kb} KB</b><br>${esc(d.selection)}<br><a class="btn small" href="${esc(d.sample_path)}" download>↓ 轻量JSON（可直接上传训练）</a><a class="btn small" href="${esc(d.sample_csv)}" download>↓ 轻量CSV</a></div>`:'<div class="notice">未取得实测子集；提供上传接口及明确标注的人工格式样例。</div>'}<p class="small-note">单位：${esc(d.unit_notes)}</p>${d.limitations?`<p class="small-note caution">${esc(d.limitations)}</p>`:''}<div class="model-links">${d.models.map(id=>{const m=MODELS.find(m=>m.id===id);return m?`<button class="btn small" data-dataset-model="${id}" data-dataset="${d.id}">${esc(m.name)} →</button>`:'';}).join('')}</div><div class="row" style="margin-top:12px">${d.download_url?`<a class="btn small" href="${esc(d.download_url)}" download>↓ 当前完整可用数据</a>`:''}<a class="btn small" href="${esc(d.raw_download_url??d.source_url)}" target="_blank" rel="noopener">原始资料来源 ↗</a>${d.path?`<a href="${esc(d.path)}" download class="btn small">↓ 模型输入JSON</a>`:''}</div></article>`).join('')}</div><div class="notice">本次采用真实来源的轻量子集，保留原始数值和样本标识；各卡片提供行数、体积、抽取规则、CSV/JSON及对应模型。完整原始资料由来源链接获取。小样本用于快速流程验证，不能代替独立现场验证；示踪剂实测未取得，PINN坐标和根因确诊标签需补充。</div><a href="./data/MONITORING_SOURCES.md" target="_blank">查看字段转换、原始标签与缺测说明 ↗</a></div></section>`;}
function unitNotes(){return `<section class="panel gap"><div class="panel-head"><h2>计量单位与指标注释</h2></div><div class="table-wrap"><table><thead><tr><th>符号 / 名称</th><th>中文注释与换算</th></tr></thead><tbody><tr><td>Sm³/d · 标准立方米/日</td><td class="wrap">按规定标准状态折算的日体积；不可与工况体积或开井时段瞬时流量直接混用。</td></tr><tr><td>MPa · 兆帕</td><td class="wrap">压力单位；1巴（bar）=0.1兆帕；1磅力/平方英寸（psi）≈0.006894757兆帕。</td></tr><tr><td>% · 百分比 / 百分点</td><td class="wrap">含水率0–100%；从20%升至23%为上升3个百分点，不能写成相对上升3%。</td></tr><tr><td>°C / min / d / m</td><td class="wrap">摄氏度 / 分钟 / 天 / 米。示踪剂流速为米/日，弥散系数为平方米/日。</td></tr><tr><td>RMS · 均方根 / 1×、2×转频</td><td class="wrap">ESP振动速度源幅值可用英寸/秒表达，1英寸/秒=25.4毫米/秒；保留发布特征源尺度。归一化转频轴不能直接当固定赫兹。</td></tr><tr><td>MAE / RMSE / R² / MAPE</td><td class="wrap">平均绝对误差 / 均方根误差 / 决定系数 / 平均绝对百分比误差；MAE和RMSE沿用预测目标单位。</td></tr><tr><td>Precision / Recall / F1</td><td class="wrap">精确率 / 召回率 / 调和平均分数，范围0–1；多类别模型显示宏平均，防止大量正常样本掩盖少数故障。</td></tr></tbody></table></div></section>`;}
function wellSelect(){const special=page==='models'&&defaultDataset(modelId)!=='volve',rs=special?(current().data.all.length?current().data.all:[...current().data.train,...current().data.test]):data,ws=[...new Set(rs.map(r=>r.well_id).filter(Boolean))];return `<select id="well-select" aria-label="井筛选"><option value="all">${special?'全部监测对象':'全部生产井'}</option>${ws.map(w=>`<option ${well===w?'selected':''}>${esc(w)}</option>`).join('')}</select>`;}
function icon(n){return ['◈','⌘','△','◎','▤','◷'][n];}
function render(){const s=current();root.innerHTML=`<div class="app ${overlay?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#overview"><div class="brandmark">中</div><div><strong>ChinaOil <span class="redtext">Sense</span></strong><small>RESERVOIR INTELLIGENCE</small></div></a><div class="row" style="padding:10px 8px;border:1px solid var(--line);border-radius:6px"><span class="tag red">研究空间</span><small>油藏生产态势感知</small></div><div class="space-label">智能生产 · 研判工作空间</div><nav class="nav">${Object.keys(titles).map((k,i)=>`<button data-page="${k}" class="${page===k?'active':''}"><span class="nav-icon">${icon(i)}</span>${titles[k]}${k==='models'?`<b>${MODELS.length}</b>`:''}${k==='alerts'?`<b>${alerts.length}</b>`:''}</button>`).join('')}</nav><div class="space-label" style="margin-top:26px">研究依据</div><div style="padding:0 12px;font-size:11px;color:var(--muted);line-height:2.1">PPT 26—30页<br>单井跟踪 · 异常识别<br>融合诊断 · 双轨校核</div><div class="side-foot"><span class="dot"></span>浏览器本地训练与计算<a href="../" target="_blank" rel="noopener">↗ 返回 GeoTwin 协同平台</a><a href="https://github.com/oilreservior123/ChinaOil-platform" target="_blank" rel="noopener">↗ GitHub 项目源码</a><small>上传数据仅在当前浏览器处理</small></div></aside><div class="topbar"><div class="row"><button class="btn small phone-menu" id="menu" aria-label="展开导航">☰</button><span class="crumb">ChinaOil / 智能生产 / <b>${titles[page]}</b></span></div><div class="right"><span class="muted"><span class="dot"></span>历史实测数据回放</span><span class="tag">PPT 26–30</span><div class="avatar">研</div></div></div><main class="main"><div class="head"><div><div class="eyebrow">PRODUCTION SITUATION AWARENESS</div><h1>${titles[page]}</h1><p>${page==='overview'?'从单井运行变化，到井组动态的一体化研判。':page==='models'?'数据接入、模型训练、独立评价与结果计算，统一工作流程。':page==='agent'?'把问题交给工具流程，保留每一步数据与诊断依据。':'生产动态、模型结果与专家经验的可追溯协同。'}</p></div><div class="row">${wellSelect()}<button class="btn" id="export-report">↓ 下载研判报告</button></div></div><div class="body-section">${page==='overview'?overview():page==='models'?workbench():page==='alerts'?alertPage():page==='agent'?agentPage():page==='data'?dataPage():experimentPage()}</div><footer><span>ChinaOil Sense · 油藏生产态势感知智能体</span><span>${esc(page==='models'?(current().origin||source):source)} · 本地计算 · 候选结论需现场核实</span></footer></main></div>`;bind();}
function lastByWell(rs){return Object.values(Object.groupBy(rs,r=>r.well_id)).map(a=>[...a].sort((a,b)=>a.date.localeCompare(b.date)).at(-1));}
function daily(rs,key){const groups=Object.groupBy(rs,r=>r.date);return Object.keys(groups).sort().map(date=>({date,v:key==='pressure'?(groups[date].some(r=>finite(r[key])&&r[key]>0)?mean(groups[date].filter(r=>finite(r[key])&&r[key]>0).map(r=>r[key])):null):groups[date].reduce((s,r)=>s+(finite(r[key])?Number(r[key]):0),0)}));}
function chart(series,{height=220,unit='',maxPoints=100,xValues=null,xLabel='日期 / 样本序列'}={}){const W=640,H=height,p={l:49,r:14,t:17,b:31};const arrays=series.map(s=>s.values.filter(v=>finite(v)));const all=arrays.flat().map(Number);if(!all.length)return '<div class="empty">等待数据或计算结果</div>';let min=Math.min(...all),max=Math.max(...all);if(min===max){min-=1;max+=1;}const pad=(max-min)*.08;min-=pad;max+=pad;const count=Math.max(...series.map(s=>s.values.length));const nx=xValues?.length===count&&xValues.every(finite),xmin=nx?Math.min(...xValues):0,xmax=nx?Math.max(...xValues):1;const x=i=>p.l+(nx?(Number(xValues[i])-xmin)/Math.max(1e-12,xmax-xmin):i/Math.max(1,count-1))*(W-p.l-p.r),y=v=>H-p.b-(v-min)/(max-min)*(H-p.t-p.b);const lines=Array.from({length:4},(_,i)=>{const v=min+(max-min)*i/3;return `<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#eeeae4" stroke-dasharray="3 4"/><text x="${p.l-9}" y="${y(v)+3}" text-anchor="end">${num(v,1)}</text>`;}).join('');return lineLegend(series)+`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series.map(s=>s.name).join('、'))}趋势图"><text x="${p.l}" y="10">${esc(unit)}</text>${lines}${series.map(s=>{const step=Math.max(1,Math.floor(s.values.length/maxPoints));const points=s.values.map((v,i)=>finite(v)&&i%step===0?`${x(i)},${y(Number(v))}`:null).filter(Boolean);return `<polyline points="${points.join(' ')}" fill="none" stroke="${s.color}" stroke-width="2" stroke-dasharray="${s.name.includes('预测')||s.name.includes('验证')?'7 4':'none'}" stroke-linejoin="round"><title>${esc(s.name)}；纵轴单位：${esc(unit||'无量纲')}</title></polyline>`;}).join('')}<text x="${p.l}" y="${H-6}">${nx?num(xmin,3):esc(series[0].labels?.[0]??'起点')}</text><text x="${W-p.r}" y="${H-6}" text-anchor="end">${nx?num(xmax,3):esc(series[0].labels?.at(-1)??'终点')}</text></svg><div class="chart-caption">横轴：${esc(xLabel)}；纵轴：${esc(unit||'无量纲')}。曲线连接观测采样点；有断档时请核对原始时间。</div>`;}
function lineLegend(a){return `<div class="legend">${a.map(s=>`<span><i style="background:${s.color}"></i>${esc(colorNames[s.color]??s.color)} · ${esc(s.name)}${s.name.includes('预测')||s.name.includes('验证')?'（虚线）':'（实线）'}</span>`).join('')}</div>`;}
function network(){const cutoff=Date.parse(data.at(-1)?.date??'2016-01-01')-90*864e5;const nodeColor=w=>{const hits=alerts.filter(a=>a.well_id===w&&Date.parse(a.date)>=cutoff);return hits.some(a=>a.level==='红')?'#e68d83':hits.some(a=>a.level==='黄')?'#d5b47d':hits.some(a=>a.level==='蓝')?'#78a4d2':'#74b8a2';};const ws=wells(),coords=ws.map((w,i)=>[w,320+Math.cos(i/ws.length*Math.PI*2-1.1)*187,143+Math.sin(i/ws.length*Math.PI*2-1.1)*82]);return `<div class="network"><div class="net-label">井网关联示意 / ${ws.length} WELLS</div><svg viewBox="0 0 640 280" role="img" aria-label="井组关联示意，非实际井位">${coords.map(([w,x,y],i)=>{const next=coords[(i+1)%coords.length];return `<line x1="${x}" y1="${y}" x2="${next[1]}" y2="${next[2]}" stroke="#c4a87866" stroke-dasharray="4 7"/>`;}).join('')}${coords.map(([w,x,y],i)=>`<g><circle cx="${x}" cy="${y}" r="18" fill="${nodeColor(w)}" opacity=".13"/><circle cx="${x}" cy="${y}" r="6" fill="${nodeColor(w)}"/><circle cx="${x}" cy="${y}" r="10" fill="none" stroke="#e0b78c55"/><text x="${x}" y="${y+28}" text-anchor="middle">${esc(w.replace('15/9-',''))}</text></g>`).join('')}<text x="320" y="135" text-anchor="middle" style="font-size:15px;fill:#e9d9bc">VOLVE</text><text x="320" y="155" text-anchor="middle" style="font-size:9px;letter-spacing:2px">PRODUCTION NETWORK</text></svg><div class="net-bottom"><span>节点颜色：末期90天实际规则等级</span><span>示意布局与连线，非真实井位或连通结论</span></div></div>`;}
function overview(){const rs=scoped(),last=lastByWell(rs),oil=mean(last.map(r=>r.oil)),recent=alerts.filter(a=>a.date>=new Date(Date.parse(rs.at(-1)?.date??'2016-01-01')-90*864e5).toISOString().slice(0,10));const q=daily(rs,'oil'),p=daily(rs,'pressure'),wc=last.filter(r=>finite(r.water_cut));const top=recent.slice(-5).reverse();return `${warningLegend()}<div class="kpis"><div class="kpi"><label>末次记录日产油合计 <span>◈</span></label><strong>${num(last.reduce((s,r)=>s+r.oil,0),0)}<small>标准立方米/日</small></strong><p>各井末次记录之和，日期可能不同</p></div><div class="kpi"><label>监测生产井 <span>◎</span></label><strong>${last.length}<small>口</small></strong><p>${num(rs.length,0)} 条历史生产记录</p></div><div class="kpi"><label>末次记录平均含水率 <span>◒</span></label><strong>${num(mean(wc.map(r=>r.water_cut)))}<small>%（百分比）</small></strong><p>单井算术平均，非油田加权含水</p></div><div class="kpi"><label>末期90天规则命中 <span>△</span></label><strong>${recent.length}<small>条</small></strong><p>待核实信号，非已确诊故障数</p></div></div><div class="grid overview"><section class="panel"><div class="panel-head"><h2>油藏生产运行态势</h2><span class="tag blue">历史数据 · ${wells().length}口生产井</span></div>${network()}<div class="well-status"><div>数据跨度<b>${data[0]?.date?.slice(0,4)}—${data.at(-1)?.date?.slice(0,4)}</b></div><div>分析模型<b>${MODELS.length} <small>套</small></b></div><div>数据来源<b>Volve <small>公开实测</small></b></div></div></section><section class="panel"><div class="panel-head"><h2>近期异常线索</h2><button class="btn text" data-page="alerts">查看全部 ↗</button></div><div class="panel-body">${top.length?top.map(a=>`<div style="border-bottom:1px solid var(--line);padding:11px 0"><div class="row" style="justify-content:space-between"><b style="font-size:12px">${esc(a.well_id)}</b><span class="tag ${a.level==='红'?'red':a.level==='黄'?'':'blue'}">${a.level}色预警</span></div><p style="font-size:11px;margin-top:5px">${esc(a.evidence)}</p><small class="muted">${a.date} · 待现场核实</small></div>`).join(''):'<div class="empty">本范围未命中近期规则</div>'}</div></section></div><div class="grid equal gap"><section class="panel"><div class="panel-head"><h2>开发动态 · 日产油趋势</h2>${lineLegend([{name:'油体积合计',color:'#b02a35'}])}</div><div class="panel-body">${chart([{name:'日产油',values:q.map(x=>x.v),labels:q.map(x=>x.date),color:'#b02a35'}],{unit:'标准立方米/日'})}</div></section><section class="panel"><div class="panel-head"><h2>地层响应 · 井下压力趋势</h2>${lineLegend([{name:'有效正压力均值',color:'#b68c50'}])}</div><div class="panel-body">${chart([{name:'压力',values:p.map(x=>x.v),labels:p.map(x=>x.date),color:'#b68c50'}],{unit:'兆帕'})}</div><div class="panel-note">仅纳入正压力记录；生产零值及原始缺失仍保留在数据中心。</div></section></div><div class="panel gap"><div class="panel-head"><h2>规则到智能的演进路径</h2><span class="tag">对应PPT第30页</span></div><div class="panel-body"><div class="stage-list">${[['01','专家规则','阈值与异常组合，建立可解释基线'],['02','模型训练','历史样本学习，验证集选择参数'],['03','双轨校核','规则与模型并行，分歧交专家仲裁'],['04','模型主导','独立测试与事件回放达标后再切换']].map(([n,t,d])=>`<div class="stage ${n==='01'?'active':''}"><small class="mono">STAGE ${n}</small><b>${t}</b><small>${d}</small></div>`).join('')}</div><div class="row"><button class="btn primary" data-page="models">进入模型实验工作台 →</button><button class="btn" data-page="agent">启动生产研判</button><small class="muted">当前阶段：规则基线与研究模型验证，未自动授予模型生产决策权。</small></div></div></div>`;}
function exampleRows(m,role='train'){if(['event3w','esp','horner','tracer'].includes(m.id)){const offset={train:0,val:80,test:160,calc:240,all:0}[role]??0;return Array.from({length:64},(_,i)=>{const k=i+offset,r={well_id:'EXAMPLE-01',sample_id:k,event_id:'人工格式-'+k,test_id:'EXAMPLE-TEST',time_min:k+1};for(const key of m.required)r[key]=key==='fault'?(i%2?'Normal':'Unbalance'):key==='event_code'?i%2:key==='log_horner'?Math.log10(1+120/(k+1)):key==='pressure'?20-2*Math.log10(1+120/(k+1)):key==='time_days'?k+1:key==='distance_m'?100:key==='concentration'?Math.exp(-(((k+1-30)/15)**2)):.1+Math.sin(i/10);return r;});}const offset={train:0,val:80,test:160,calc:240,all:0}[role]??0;return Array.from({length:64},(_,i)=>{const k=i+offset;const r={well_id:'EXAMPLE-01',date:new Date(Date.UTC(2025,0,1+k)).toISOString().slice(0,10)};for(const key of m.required)r[key]=key==='root_cause'?(i%2?'供液能力下降':'泵况故障'):key==='x'?.2+(i%10)*.06:key==='t'?.1+i*.01:key==='water_cut'?20:key==='injection'?180:key==='pressure'?18-i*.02:key==='water'?20:key==='liquid'?120-i*.2:100-i*.2;if(m.id==='stgnn')return [r,{...r,well_id:'EXAMPLE-02',oil:r.oil*.95}];return r;}).flat();}
function uploadBox(role,title){const s=current(),m=spec();return `<div class="drop"><strong>${title} <span class="tag ${s.data[role].length?'green':''}">${s.data[role].length?num(s.data[role].length,0)+'行':'未上传'}</span></strong><p>CSV / JSON / XLSX · ${role==='calc'?'计算不强制确诊标签；评价需标签':'字段见下方说明'}<br>必需：${(role==='calc'?inferenceRequired(m.id):m.required).map(esc).join('、')||'well_id、date（目标值可不提供）'}</p><input type="file" accept=".csv,.json,.xlsx,.xls" data-upload="${role}" aria-label="${title}"><button class="btn text small" style="margin-top:9px" data-example="${role}">↓ ${title}格式样例</button></div>`;}
function metricHTML(m){if(!m)return '<div class="notice">尚无可用评价指标。回归模型需真实目标值；异常模型需label；诊断模型需root_cause。没有标签时不计算准确率。</div>';const keys=['MAE','RMSE','R2','MAPE','Accuracy','Precision','Recall','F1','FPR','N','UnknownTrueCount'].filter(k=>k in m);return `<div class="metric-grid">${keys.map(k=>`<div class="metric"><label>${k} · ${metricName[k]}</label><b>${fmt(m[k],k==='N'?0:3)}${k==='MAPE'?'%':''}</b></div>`).join('')}</div><small class="muted">MAE/RMSE沿用预测目标单位；分类指标为0–1。R²在真实值恒定时未定义。MAPE排除零真实值。</small>`;}
function workbench(){const m=spec(),s=current();return `<div class="model-strip">${MODELS.map(x=>`<button data-model="${x.id}" class="${m.id===x.id?'active':''}">${x.name}</button>`).join('')}</div><div class="grid workbench"><section class="panel"><div class="panel-body"><div class="row"><span class="tag red">${m.tag}</span><span class="mono muted" style="font-size:10px">${m.en}</span></div><h2 class="model-title">${m.name}</h2><p class="desc">${m.note}</p><div class="subtabs">${[['data','01 数据与划分'],['train','02 训练与评价'],['calc','03 计算与下载']].map(([id,t])=>`<button data-tab="${id}" class="${s.tab===id?'active':''}">${t}</button>`).join('')}</div>${s.tab==='data'?dataTab(m,s):s.tab==='train'?trainTab(m,s):calcTab(m,s)}</div></section><aside><section class="panel"><div class="panel-head"><h2>模型名称与结构</h2><span class="tag">实际实现</span></div><div class="architecture">${m.structure.map((t,i)=>`${i?'<div class="arch-arrow">↓</div>':''}<div class="arch-node"><span>0${i+1}</span>${t}</div>`).join('')}</div><p class="formula">${m.formula}</p><div class="panel-body"><h3>公式符号与参数注释</h3><p class="desc">${esc(parameterNotes[m.id])}</p></div><div class="panel-body"><div class="statrow"><span>预测 / 辨识目标</span><b>${fieldInfo[m.target]?.[0]??m.target}</b></div><div class="statrow"><span>实际训练时长</span><b>${s.fit?num(s.fit.duration,3)+' 秒':'尚未训练'}</b></div><div class="statrow"><span>运行位置</span><b>当前浏览器</b></div><div class="statrow"><span>数据上传到服务器</span><b>否</b></div><div class="statrow"><span>训练样本</span><b>${s.fit?num(s.fit.trainedRows,0):'—'}</b></div></div></section><section class="panel gap"><div class="panel-head"><h2>输入特征与中文单位</h2></div><div class="table-wrap"><table class="field-dict"><thead><tr><th>字段</th><th>含义 / 单位</th></tr></thead><tbody>${['well_id',...(['event3w','esp','horner','tracer'].includes(m.id)?[m.id==='event3w'?'event_id':m.id==='esp'?'sample_id':m.id==='horner'?'test_id':'time_days']:['date']),...new Set(m.required)].map(k=>`<tr><td class="mono">${k}</td><td>${fieldInfo[k]?.join(' · ')??k}</td></tr>`).join('')}</tbody></table></div>${['event3w','esp'].includes(m.id)?`<div class="panel-note">${m.id==='event3w'?eventNames.map((n,i)=>i+'：'+n).join('；'):Object.entries(faultNames).map(([k,v])=>k+'：'+v).join('；')}</div>`:''}<div class="panel-note">不同模型的数据集独立保存。刷新会清空，实验记录请及时导出。</div></section></aside></div>`;}
function dataTab(m,s){const n=s.data.train.length+s.data.val.length+s.data.test.length;return `${datasetChoice(m,s)}<div class="notice">先上传整体数据并划分，或分别上传训练 / 验证 / 测试集。浏览器接受归一化字段，原始3W需按字段映射转换。${['tcn','stgnn','gdn'].includes(m.id)?'时序模型优先按时间划分，随机划分会破坏连续窗口并造成相邻信息泄漏。':''}</div><div class="row" style="margin-top:15px"><button class="btn primary" id="load-light">载入轻量实测样本并划分</button><button class="btn" id="load-real">载入当前完整可用资料</button><button class="btn" id="load-teaching">载入格式教学样例</button></div><div class="upload-grid">${uploadBox('all','整体数据上传')}${uploadBox('train','模型训练数据')}${uploadBox('val','模型验证数据')}${uploadBox('test','模型测试数据')}</div><div class="row"><label class="input-label">训练占比 %<input id="ratio-train" type="number" min="1" max="98" value="70"></label><label class="input-label">验证占比 %<input id="ratio-val" type="number" min="1" max="98" value="15"></label><label class="input-label">测试占比 %<input id="ratio-test" type="number" min="1" max="98" value="15"></label><label class="input-label">划分方式<select id="split-method"><option value="time" ${!['arps','crm','horner','esp','event3w'].includes(m.id)?'selected':''}>全局按时间</option><option value="well-time" ${['arps','crm','horner'].includes(m.id)?'selected':''}>逐井按时间（逐井模型建议）</option><option value="random" ${['event3w','esp'].includes(m.id)?'selected':''}>随机划分</option><option value="well">按井分组（泛化评估）</option></select></label><label class="input-label">随机种子<input id="seed" type="number" value="42"></label></div><div class="splitbar">${[70,15,15].map(x=>`<span style="width:${x}%"></span>`).join('')}</div><div class="row" style="justify-content:space-between"><small class="muted">系统建议：70%训练 / 15%验证 / 15%测试 · 已就绪 ${num(n,0)}行</small><button class="btn" id="split">执行整体数据划分</button></div>${coverageBox(s)}<div class="schema">${m.required.map(k=>`<code>${k}</code>`).join('')}</div><p style="font-size:11px;color:var(--muted);margin-bottom:8px">输入示例（人工构造，仅展示格式；不用于证明模型效果）</p><pre class="sample">${esc(csv(exampleRows(m).slice(0,2)).replace(/^\ufeff/,''))}</pre><div class="row" style="margin-top:14px"><button class="btn" id="export-splits">↓ 导出划分与来源记录</button><button class="btn primary" data-tab="train">进入训练与评价 →</button></div>${s.origin?`<div class="small-note">当前数据来源：${esc(s.origin)}</div>`:''}`;}
function trainTab(m,s){const active=s.metrics[s.role];return `${coverageBox(s)}<div class="notice ${s.origin?.includes('人工')?'error':''}">当前数据：${esc(s.origin??'尚未上传')} · ${s.origin?.includes('人工')?'教学样例指标不能视为现场效果。':'评价指标只适用于本批数据及当前划分。'}</div><div class="row" style="margin-top:17px"><label class="input-label">训练轮次<input id="epochs" type="number" min="1" max="150" value="${s.options?.epochs??10}"></label>${['stgnn','pinn'].includes(m.id)?'<label class="input-label">物理损失权重 λ<input id="lambda" type="number" min="0" max="10" step="0.01" value="0.1"></label>':''}${m.id==='pinn'?'<label class="input-label">归一化扩散系数 α<input id="alpha" type="number" min="0.0001" max="1" step="0.01" value="0.02"></label>':''}<button class="btn primary" id="train" ${s.busy?'disabled':''}>${s.busy?'训练中…':m.id==='rules'?'校准规则与CUSUM':'开始实际训练'}</button><button class="btn" id="download-model" ${!s.fit||s.busy?'disabled':''}>↓ 模型参数 / 权重</button></div><div class="progress"><i style="width:${s.progress??0}%"></i></div><div id="run-status" class="run-status">${s.busy?'训练进行中':s.fit?`训练完成 · ${num(s.fit.duration,3)}秒 · ${s.fit.trainedRows}行`:'等待训练：训练集'+s.data.train.length+'行 / 验证集'+s.data.val.length+'行 / 测试集'+s.data.test.length+'行'}</div>${s.error?`<div class="notice error">${esc(s.error)}</div>`:''}<div class="row" style="margin-top:17px"><button class="btn ${s.role==='val'?'primary':''}" data-eval="val" ${s.busy?'disabled':''}>验证集评价</button><button class="btn ${s.role==='test'?'primary':''}" data-eval="test" ${s.busy?'disabled':''}>独立测试集评价</button><span class="tag">${s.role==='val'?'验证集':'测试集'}指标</span></div><div id="metrics">${metricHTML(active)}</div><div class="grid equal gap"><div><h3>实际训练损失</h3><div id="loss-chart">${s.fit&&['rules','arps','crm','horner','tracer'].includes(m.id)?'<div class="empty">数理拟合 / 校准模型不产生神经网络损失曲线；请查看参数与独立评价。</div>':chart([{name:'训练损失',values:s.fit?.history.map(x=>x.loss)??[],color:'#b02a35',labels:s.fit?.history.map(x=>String(x.epoch))??[]},...(s.fit?.history.some(h=>h.val_loss!==undefined)?[{name:'验证损失',values:s.fit.history.map(h=>h.val_loss),color:'#477ca6'}]:[])],{unit:'损失值',xLabel:'训练轮次'})}</div></div><div><h3>${['gdn','rules'].includes(m.id)?'异常评分':m.id==='diagnosis'?'确诊标签混淆统计':'实测与预测对比'}</h3><div id="fit-chart">${resultPlot(s)}</div></div></div>${s.fit?.history.length?`<div class="historylog">${s.fit.history.slice(-6).map(h=>`轮次 ${h.epoch} · loss ${num(h.loss,6)} ${h.val_loss!==undefined?'· val_loss '+num(h.val_loss,6):''}`).join('<br>')}</div>`:''}<div class="notice">${['rules','arps','crm','horner','tracer'].includes(m.id)?'本模型使用数理拟合或规则校准，不存在神经网络训练轮次；耗时为实测计算耗时。':'验证集用于独立监测；当前固定轮次训练不自动用测试指标选模型。'} 测试结果不会回流训练；外部上传集仍需检查井、事件及时间是否重叠。</div>`;}
function resultPlot(s){if(!s.results.length)return '<div class="empty">完成训练后，点击验证集或测试集评价</div>';if(['diagnosis','event3w','esp'].includes(modelId)){const m=s.metrics[s.role];return m?`<div class="classification-matrix">${(modelId==='diagnosis'?['TP','FP','FN','TN']:['Accuracy','Precision','Recall','F1']).map(k=>`<div>${metricName[k]??k}<b>${fmt(m[k])}</b></div>`).join('')}</div><div class="small-note">${modelId==='diagnosis'?'多标签按位统计':'多类别指标为宏平均；未见真实类别不会被忽略。'}</div>`:'<div class="empty">没有真实标签，无法绘制评价统计</div>';}
let rs=s.results.filter(r=>!['rules','arps','crm','tcn','stgnn','gdn'].includes(modelId)||well==='all'||r.well_id===well),note='';if(well==='all'&&['arps','crm','tcn','stgnn'].includes(modelId)&&new Set(rs.map(r=>r.well_id)).size>1){const w=rs[0]?.well_id;rs=rs.filter(r=>r.well_id===w);note=`<div class="small-note">曲线预览井${esc(w)}；上方指标仍为本批全部对象。可用井筛选查看其他井，避免多井曲线错误连线。</div>`;}if(modelId==='horner'&&rs.length){const id=rs[0].test_id;rs=rs.filter(r=>r.test_id===id).sort((a,b)=>a.log_horner-b.log_horner);note=`<div class="small-note">曲线预览首个测试：${esc(id)}。其他测试见完整结果下载，避免把不同测试直接连线。</div>`;}if(['rules','gdn'].includes(modelId))return chart([{name:'异常评分',values:rs.map(r=>r.score??r.prediction),labels:rs.map(r=>r.date),color:'#b02a35'}],{unit:'无量纲评分'});const missing=s.results.filter(r=>r.prediction===null||r.prediction===undefined);const labels=rs.map(r=>r.date??String(r.time_min??r.time_days??r.sample_id??''));return note+chart([{name:'真实观测',values:rs.map(r=>r.actual),labels,color:'#b68c50'},{name:'模型预测',values:rs.map(r=>r.prediction),labels,color:'#b02a35'}],{unit:fieldInfo[spec().target]?.[1]??'',xValues:modelId==='horner'?rs.map(r=>r.log_horner):modelId==='tracer'?rs.map(r=>r.time_days):null,xLabel:modelId==='horner'?'霍纳对数时间log10(H)，无量纲':modelId==='tracer'?'注入后经过时间，天':'日期 / 样本序列'})+(missing.length?`<div class="notice error">本批${missing.length}条未覆盖记录未生成预测，也未计入误差指标。请补充其历史训练资料。</div>`:'');}
function calcTab(m,s){return `<div class="notice ${s.origin?.includes('人工')?'error':''}">来源：${esc(s.origin??'用户上传')}。${s.origin?.includes('人工')?'人工教学样例结果，不代表现场效果。':''}</div><div class="notice">计算使用当前模型训练出的参数。时序模型需每井至少9天连续历史资料；第一条预测在第9天。当前结果不会假装成未来多步外推。</div>${uploadBox('calc','模型计算输入数据')}<div class="row" style="margin:14px 0"><button class="btn" id="calc-use-test">使用当前测试集</button><button class="btn primary" id="predict" ${s.busy?'disabled':''}>运行模型计算</button><button class="btn" id="download-results" ${!s.results.length?'disabled':''}>↓ 下载完整计算结果</button></div>${s.error?`<div class="notice error">${esc(s.error)}</div>`:''}${resultPlot(s)}${s.results.length?`<p class="small-note">本批输入 ${s.results.length} 条，成功 ${s.results.filter(r=>r.prediction!==null&&r.prediction!==undefined).length} 条；预览前20条。完整下载包含全部结果及原始特征。</p><div class="table-wrap">${resultTable(s.results.slice(0,20))}</div><div class="notice">${conclusion(s)}</div>`:'<div class="empty">上传计算数据，完成训练后运行计算</div>'}`;}
function resultTable(rows){return `<table><thead><tr><th>井 / 测试对象</th><th>日期 / 样本 / 时间</th><th>真实值 / 标签</th><th>计算结果</th><th>异常评分</th><th>覆盖状态与说明</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.well_id??r.test_id??'—')}</td><td>${esc(r.date??r.sample_id??r.time_min??r.time_days??r.event_id??'—')}</td><td>${esc(r.root_cause??r.fault??r.event_code??(r.label!==undefined?r.label:fmt(r.actual)))}</td><td>${r.prediction===null||r.prediction===undefined?'—':['event3w','esp'].includes(modelId)?esc(labelNote(r.prediction)):typeof r.prediction==='number'?num(r.prediction,3):esc(r.prediction)}</td><td>${fmt(r.score)}</td><td class="wrap">${r.prediction===null?'<span class="tag">未覆盖</span>':esc(r.status??'已计算')}${r.reason?'<br>'+esc(r.reason):''}</td></tr>`).join('')}</tbody></table>`;}
function conclusion(s){const m=s.metrics[s.role];if(!s.results.length)return '暂无模型结果，不生成诊断结论。';const valid=s.results.filter(r=>r.prediction!==null&&r.prediction!==undefined),missing=s.results.length-valid.length;if(!valid.length)return `本批${missing}条均未被当前模型覆盖，没有计算预测或评价指标。请将对应井/测试的历史资料加入训练，或采用逐井按时间划分；不使用测试集补训。`;if(['event3w','esp'].includes(modelId))return `完成${valid.length}条真实资料分类，宏平均F1=${fmt(m?.F1)}。3W为观测事件类别，ESP为设备原始故障类别；不把两者直接作为地层因果诊断。`;if(['gdn','rules'].includes(modelId))return `识别到${s.results.filter(r=>r.prediction===1).length}条候选异常。请先复核计量、停井和措施记录，再联合示功图、试井与示踪剂判断。${m?'本批F1='+fmt(m.F1)+'，需按事件回放核验提前量。':'缺少确认标签，不能说明准确率或真实故障数量。'}`;if(modelId==='diagnosis')return '已输出候选多标签原因及概率，按井归集证据后交专家审核。当前分类学习的是已标注映射，不构成因果证明。';return `已完成${valid.length}条预测，${missing}条未覆盖并保留原因。${m?.RMSE!==undefined?'本批RMSE='+fmt(m.RMSE)+'，R²='+fmt(m.R2)+'。':''}建议检查大残差所对应的开关井、注采调整和措施记录；不直接以预测值下发生产制度。`;}
function alertPage(){const rs=scoped(),ws=lastByWell(rs),a=alerts.filter(a=>well==='all'||a.well_id===well);return `${warningLegend()}<div class="grid overview"><section class="panel"><div class="panel-head"><h2>单井分级分类跟踪</h2><span class="tag">对应PPT第27页</span></div><div class="table-wrap"><table><thead><tr><th>生产井</th><th>管理分类</th><th>末次记录</th><th>日产油</th></tr></thead><tbody>${ws.map(r=>`<tr><td>${esc(r.well_id)}</td><td>${classifyWell(rs.filter(x=>x.well_id===r.well_id))}</td><td>${r.date}</td><td>${num(r.oil)}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">正式投产6个月内为新井，措施3个月内为措施井；缺失台账时不以首条观测日期冒充投产日期。常规井A/B/C需现场产量贡献划界。</div></section><section class="panel"><div class="panel-head"><h2>现场规则参数</h2><span class="tag">研究初值</span></div><div class="panel-body"><div class="rule-list"><label>连续3天产油下降阈值（%）<input id="rule-decline" type="number" value="15" min="1" max="99"></label><label>相邻井下压力变化（兆帕）<input id="rule-pressure" type="number" value="0.5" min="0.01" step="0.1"></label></div><button id="rescan" class="btn primary" style="margin-top:15px">按当前阈值重新扫描</button><p class="small-note">实现持续产油、液量、含水、压力、注水、泵效与多信号融合规则；缺少特征时不执行对应规则。</p></div></section></div><section class="panel gap"><div class="panel-head"><h2>异常线索与融合研判建议</h2><div class="row"><span class="tag red">${a.length}条命中</span><button class="btn small" id="download-alerts">↓ 下载预警</button></div></div><div class="table-wrap" style="max-height:530px"><table><thead><tr><th>等级</th><th>井号 / 日期</th><th>触发证据</th><th>候选解释</th><th>核查与处置建议</th></tr></thead><tbody>${a.slice(-120).reverse().map(r=>`<tr><td><span class="alert-dot ${r.level}"></span>${r.level}</td><td>${esc(r.well_id)}<br><small class="muted">${r.date}</small></td><td class="wrap">${esc(r.evidence)}</td><td class="wrap">${esc(r.cause)}</td><td class="wrap">${esc(r.action)}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">显示最近120条；下载包含全部。井下压力与井口油压/套压不是同一指标，不能直接套用PPT中的压力规则作故障确诊。</div></section><div class="notice">多源诊断：产量下降+动液面加深+供液不足示功图，可形成供液能力下降线索；产量下降+泵漏失示功图+泵效下降，可形成泵况故障线索。公开数据缺少这些同步证据，系统不会自动确认上述根因。</div>`;}
function agentPage(){return `<div class="grid workbench"><section class="panel"><div class="panel-head"><h2>生产研判对话</h2><span class="tag red">工具编排智能体</span></div><div class="panel-body assistant"><div class="prompt">可提问生产趋势、异常井、含水变化、压力变化或模型效果。系统会读取当前井范围、调用规则与已训练模型，输出可追溯证据。</div><div class="quick">${['分析当前井组生产态势','哪些井需要优先核查？','分析含水变化与压力响应','预测产量并给出建议'].map(t=>`<button data-prompt="${t}">${t}</button>`).join('')}</div><div id="agent-answer">${answer||'<div class="empty">选择一个任务，开始生产研判。</div>'}</div><form id="ask-form" class="question"><input id="question" placeholder="例如：分析15/9-F-12的产量下降线索" aria-label="输入研判任务" required><button class="btn primary" type="submit">执行研判 →</button></form><div class="small-note">当前为本地规则与模型工具驱动的智能体，不调用外部大语言模型。支持任务路由、证据汇总和报告生成。</div></div></section><aside><section class="panel"><div class="panel-head"><h2>本次研判工具链</h2></div><div class="panel-body">${[['读取数据','按井、日期与字段可用性确定分析范围'],['执行分析','规则扫描、趋势统计或Arps预测'],['证据校核','标记缺失工况、措施与确诊标签'],['输出建议','按证据给出核查优先级，保留人工审核']].map(([t,d],i)=>`<div class="analysis-step"><span>${i+1}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<div class="source-box">当前来源：${esc(source)}<br>样本：${num(scoped().length,0)}行 · ${well==='all'?'全部井':esc(well)}<br>仅当前会话保存。可下载报告与反馈记录。</div></div></section><section class="panel gap"><div class="panel-head"><h2>专家审核与反馈</h2></div><div class="panel-body"><label class="input-label">确诊 / 处理记录<textarea id="feedback" rows="4" placeholder="井号、日期、现场确认原因、处置措施与效果"></textarea></label><button id="save-feedback" class="btn" style="margin-top:12px">↓ 保存反馈记录</button><p class="small-note">反馈只导出归档，不会未经核验自动加入训练集。</p></div></section></aside></div>`;}
function dataPage(){const rs=scoped(),keys=['well_id','date','oil','water','pressure','injection','water_cut'];return `${catalogPanel()}${unitNotes()}<div class="grid overview gap"><section class="panel"><div class="panel-head"><h2>公开数据与自有资料接入</h2><span class="tag green">本地处理</span></div><div class="panel-body"><p class="desc">当前内置Volve实测生产记录。可上传统一字段的CSV、JSON或XLSX替换分析范围。示功图、试井、示踪剂属于不同模态，需先提取特征或由专项解释模块转换。</p><div class="drop" style="margin-top:15px"><strong>替换当前分析数据</strong><p>需well_id、date、oil、water、pressure；缺失值保留，不以0静默补齐。</p><input id="global-upload" type="file" accept=".csv,.json,.xlsx,.xls" aria-label="上传全局生产数据"></div><div class="row" style="margin-top:13px"><button id="reset-real" class="btn">恢复Volve公开数据</button><button id="download-current" class="btn primary">↓ 下载当前范围数据</button></div><div class="notice">内置injection为油田总注水体积，非逐对井分配。含水率由油水体积派生；压力由巴换算为兆帕。未生成故障、投产或措施标签。</div></div></section><section class="panel"><div class="panel-head"><h2>数据完整性</h2><span class="tag">当前范围 ${num(rs.length,0)}行</span></div><div class="panel-body feature-rank">${keys.slice(2).map(k=>{const rate=rs.length?100*rs.filter(r=>finite(r[k])).length/rs.length:0;return `<div class="rank"><span>${fieldInfo[k][0]}</span><div class="bar"><i style="width:${rate}%"></i></div><span>${num(rate)}%</span></div>`;}).join('')}<small class="muted">这里统计非缺失数值率，不代表数据真实、准确或已通过联合质控。</small></div></section></div><section class="panel gap"><div class="panel-head"><h2>生产数据预览</h2><span class="tag">前30条</span></div><div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${fieldInfo[k][0]}</th>`).join('')}</tr></thead><tbody>${rs.slice(0,30).map(r=>`<tr>${keys.map(k=>`<td>${typeof r[k]==='number'?num(r[k],3):esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel gap"><div class="panel-head"><h2>训练资料来源与适用边界</h2></div><div class="panel-body"><div class="statrow"><span>Volve · 生产趋势与规则验证</span><a href="./data/SOURCES.md" target="_blank">查看转换和来源说明 ↗</a></div><div class="statrow"><span>3W · 实测带标签异常数据</span><a href="https://github.com/petrobras/3W" target="_blank" rel="noopener">官方数据源 ↗</a></div><div class="statrow"><span>DST · 压力恢复与地层压力</span><a href="https://data.mendeley.com/datasets/px455bwjg2/2" target="_blank" rel="noopener">官方数据源 ↗</a></div><div class="statrow"><span>ESPset · 电潜泵振动故障</span><a href="https://data.mendeley.com/datasets/m268jsw339/3" target="_blank" rel="noopener">官方数据源 ↗</a></div><div class="notice">上述数据来自不同对象，不能直接按数字井号关联。3W只取WELL-实测文件，转为本页统一字段后导入。ESP频谱不是示功图，不能替代抽油机泵况。示踪剂原始附件尚缺。</div></div></section>`;}
function experimentPage(){return `<section class="panel"><div class="panel-head"><h2>实验与模型比较</h2><button class="btn small" id="export-experiments">↓ 导出实验记录</button></div><div class="panel-body">${experiments.length?experiments.slice().reverse().map(e=>`<div class="run-card"><div class="row" style="justify-content:space-between"><b>${esc(e.name)}</b><span class="tag green">${num(e.duration,3)}秒</span></div><p class="small-note">${esc(e.time)} · 训练${e.train} / 验证${e.val} / 测试${e.test}行 · ${esc(e.origin??'用户上传')}</p><div class="small-note">测试集：${e.metrics?Object.entries(e.metrics).filter(([k])=>['RMSE','R2','F1','Accuracy'].includes(k)).map(([k,v])=>k+' '+fmt(v)).join(' · '):'未评价或缺少真实标签'}</div></div>`).join(''):'<div class="empty">完成一次训练后，实验会自动记录在这里。</div>'}<div class="notice">“模型主导”不能只凭单次准确率切换。应综合独立测试、分井稳定性、事件召回、误报次数、预警提前量和处置效果，完成专家审核。当前未自动启用在线学习。</div></div></section>`;}
async function readFile(file){if(!file)throw Error('未选择文件');if(file.size>30*1024*1024)throw Error('单文件上限30MB；大型频谱与Parquet请先转换或分批');let rows;if(/\.xlsx?$/i.test(file.name)){if(!globalThis.XLSX)throw Error('Excel解析器未加载');const w=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});rows=XLSX.utils.sheet_to_json(w.Sheets[w.SheetNames[0]],{defval:''});rows=rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v instanceof Date?v.toISOString().slice(0,10):v])));}else if(/\.json$/i.test(file.name)){const j=JSON.parse(await file.text());rows=Array.isArray(j)?j:j.rows;if(!Array.isArray(rows))throw Error('JSON须为对象数组，或含rows数组的对象');}else rows=parseCSV(await file.text());return normalizeRows(rows);}
function invalidate(s){s.fit?.network?.dispose();s.fit=null;s.results=[];s.metrics={};s.error='';}
function overlap(s,role){if(role==='train')return;const key=r=>recordIdentity(r,modelId);const seen=new Set([...s.data.train,...(role==='test'?s.data.val:[])].map(key));if(s.data[role].some(r=>seen.has(key(r))))throw Error('训练、验证或测试集存在相同井/时间记录，请重新独立划分，避免数据泄漏');}
function bind(){document.querySelectorAll('[data-dataset-model]').forEach(e=>e.onclick=()=>{modelId=e.dataset.datasetModel;well='all';current().datasetId=e.dataset.dataset;current().tab='data';page='models';render();});$('#model-dataset')?.addEventListener('change',e=>{const st=current();if(st.busy)return;invalidate(st);st.data={train:[],val:[],test:[],all:[],calc:[]};st.datasetId=e.target.value;st.origin='';render();});document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{page=e.dataset.page;if(!wells().includes(well))well='all';overlay=false;render();});$('#menu')?.addEventListener('click',()=>{overlay=!overlay;render();});$('#well-select')?.addEventListener('change',e=>{well=e.target.value;render();});document.querySelectorAll('[data-model]').forEach(e=>e.onclick=()=>{modelId=e.dataset.model;if(defaultDataset(modelId)!=='volve')well='all';render();});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{current().tab=e.dataset.tab;render();});document.querySelectorAll('[data-example]').forEach(e=>e.onclick=()=>save(`${modelId}_${e.dataset.example}_人工格式样例.csv`,csv(exampleRows(spec(),e.dataset.example))));
 document.querySelectorAll('[data-upload]').forEach(e=>e.onchange=async()=>{const s=current(),m=spec(),role=e.dataset.upload;try{const rs=await readFile(e.files[0]);validateRows(rs,role==='calc'?inferenceRequired(m.id):m.required);s.data[role]=rs;s.origin=`用户上传：${e.files[0].name}`;if(['train','all'].includes(role))invalidate(s);else {s.metrics[role]=null;s.results=[];}toast(`${role}已载入${rs.length}行`);render();}catch(err){toast(err.message);}});
 $('#split')?.addEventListener('click',()=>{try{performSplit();render();}catch(e){toast(e.message);}});
 for(const loaderId of ['load-real','load-light'])$('#'+loaderId)?.addEventListener('click',async()=>{try{const s=current(),m=spec(),entry=catalog.find(d=>d.id===(s.datasetId??defaultDataset(m.id)));if(!entry?.available)throw Error('该来源原始实测资料尚未取得，请通过上传接口接入；不会用人工数据替代');if(['pinn','diagnosis'].includes(m.id))throw Error(m.id==='pinn'?'现有试井数据缺少实际空间x和归一化t；请补充实际坐标，或使用Horner模型解释DST。':'内置公开资料没有该模型需要的现场确诊root_cause；3W观测事件应使用专门的3W事件分类模型。');const lightweight=loaderId==='load-light';let input;if(lightweight){if(!entry.sample_path)throw Error('该来源没有可用实测轻量样本，请上传或使用明确标注的格式教学样例');const response=await fetch(entry.sample_path);if(!response.ok)throw Error('轻量样本载入失败');input=normalizeRows(await response.json());}else if(entry.id==='volve')input=m.id==='stgnn'?data:scoped();else{const response=await fetch(entry.path);if(!response.ok)throw Error('数据文件载入失败');input=normalizeRows(await response.json());}let usable=selectUsableRows(input,m.required);let removed=0;if(m.id==='horner'){usable=usable.filter(r=>finite(r.time_min));const counts=Object.groupBy(usable,r=>r.test_id??r.well_id);const before=usable.length;usable=usable.filter(r=>counts[r.test_id??r.well_id].length>=10);removed=before-usable.length;}if(usable.length<20)throw Error('完整有效样本不足20行，请补充资料或选择适配模型');s.data.all=usable;s.datasetId=entry.id;s.options={...s.options,epochs:10};s.origin=`${entry.title}${lightweight?' · 轻量实测子集':''}：载入${usable.length}/${input.length}行完整合规特征；缺失/越界行不用于训练，原始数据保留${removed?'；短测试段排除'+removed+'行':''}`;if(lightweight&&entry.id==='volve')$('#split-method').value='well-time';performSplit();toast('实测资料已载入，并按所选方案划分');render();}catch(e){toast(e.message);}});
 $('#load-teaching')?.addEventListener('click',()=>{const s=current();s.data.all=normalizeRows(exampleRows(spec(),'all'));s.origin='人工构造格式教学样例，不代表现场效果';try{performSplit();render();toast(s.origin);}catch(e){toast(e.message);}});
 $('#export-splits')?.addEventListener('click',()=>{const s=current();save(modelId+'_数据划分与来源.json',JSON.stringify({model:modelId,origin:s.origin,split:s.split,train:s.data.train,validation:s.data.val,test:s.data.test},null,2),'application/json');});
 $('#train')?.addEventListener('click',train);
 document.querySelectorAll('[data-eval]').forEach(e=>e.onclick=()=>evaluateRole(e.dataset.eval));
 $('#calc-use-test')?.addEventListener('click',()=>{current().data.calc=[...current().data.test];toast('已复制测试集到计算输入');render();});
 $('#predict')?.addEventListener('click',async()=>{const s=current();try{if(!s.fit)throw Error('请先训练当前模型');if(s.busy)throw Error('训练进行中，请稍后计算');s.results=await predictModel(s.fit,s.data.calc);s.metrics.calc=evaluate(s.fit,s.results);s.role='calc';s.error='';render();toast('模型计算完成，结果可下载');}catch(e){s.error=e.message;render();}});
 $('#download-results')?.addEventListener('click',()=>save(modelId+'_完整计算结果.csv',csv(current().results.map(r=>({...r,probabilities:r.probabilities?JSON.stringify(r.probabilities):'',model_name:spec().name,prediction_note:labelNote(r.prediction),source:current().origin,training_seconds:current().fit?.duration})))));
 $('#download-model')?.addEventListener('click',async()=>{try{save(modelId+'_模型权重参数.json',JSON.stringify(await exportFit(current().fit)),'application/json');}catch(e){toast(e.message);}});
 $('#rescan')?.addEventListener('click',()=>{const d=Number($('#rule-decline').value),p=Number($('#rule-pressure').value);if(!(d>0&&d<100&&p>0))return toast('阈值须为有效正数，产油降幅小于100%');alerts=ruleScan(data,{decline:d,pressure:p});render();toast('规则重新扫描完成');});
 $('#download-alerts')?.addEventListener('click',()=>save('生产预警_待现场核实.csv',csv(alerts.filter(a=>well==='all'||a.well_id===well))));
 document.querySelectorAll('[data-prompt]').forEach(e=>e.onclick=()=>runAgent(e.dataset.prompt));$('#ask-form')?.addEventListener('submit',e=>{e.preventDefault();runAgent($('#question').value);});
 $('#save-feedback')?.addEventListener('click',()=>{const text=$('#feedback').value.trim();if(!text)return toast('请填写现场确认与处置内容');save('专家仲裁反馈.json',JSON.stringify({time:new Date().toISOString(),well,feedback:text,analysis:answer.replace(/<[^>]+>/g,''),status:'待审核，不自动入训练'},null,2),'application/json');});
 $('#global-upload')?.addEventListener('change',async e=>{try{const rs=await readFile(e.target.files[0]);validateRows(rs,['oil','water','pressure']);if(rs.some(r=>!r.date||!r.well_id))throw Error('缺少well_id或date');data=rs.sort((a,b)=>a.date.localeCompare(b.date));well='all';source='用户上传：'+e.target.files[0].name;alerts=ruleScan(data);render();toast('分析数据已更新；各模型原有训练集保持独立');}catch(err){toast(err.message);}});
 $('#reset-real')?.addEventListener('click',async()=>{try{await loadData();well='all';source='Volve公开实测生产资料';render();}catch(e){toast(e.message);}});$('#download-current')?.addEventListener('click',()=>save('当前生产数据.csv',csv(scoped())));$('#export-experiments')?.addEventListener('click',()=>save('模型实验记录.json',JSON.stringify(experiments,null,2),'application/json'));
 $('#export-report')?.addEventListener('click',()=>save('油藏生产研判报告.md',report(),'text/markdown;charset=utf-8'));
 if(current().busy)document.querySelectorAll('[data-upload],#load-real,#load-light,#load-teaching,#split,#calc-use-test').forEach(e=>e.disabled=true);
}
function performSplit(){const s=current();if(!s.data.all.length)throw Error('请先上传整体数据');const ratios=['train','val','test'].map(k=>Number($('#ratio-'+k)?.value??(k==='train'?70:15)));const method=$('#split-method')?.value??(['arps','crm','horner'].includes(modelId)?'well-time':['event3w','esp'].includes(modelId)?'random':'time'),seed=Number($('#seed')?.value??42);const [train,val,test]=splitData(s.data.all,ratios,method,seed);invalidate(s);s.data.train=train;s.data.val=val;s.data.test=test;s.split={method,seed,ratios,counts:[train.length,val.length,test.length]};if(method==='random')toast('已随机划分。时序预测建议改用按时间划分，防止窗口破坏或信息泄漏。');}
async function train(){const s=current(),id=modelId,m=spec();if(s.busy)return;const options={epochs:Number($('#epochs')?.value??20),lambda:Number($('#lambda')?.value??.1),alpha:Number($('#alpha')?.value??.02)};s.options=options;s.busy=true;s.error='';s.progress=0;render();try{if(!s.data.train.length)throw Error('请先载入训练数据');if(s.data.val.length)overlap(s,'val');if(s.data.test.length)overlap(s,'test');const old=s.fit;s.fit=await trainModel(id,s.data.train,s.data.val,options,(e,n,loss)=>{s.progress=Math.round(100*e/n);if(page==='models'&&modelId===id&&s.tab==='train'&&$('#run-status')){$('#run-status').textContent=`训练轮次 ${e}/${n} · 损失 ${num(loss,6)}`;$('.progress i').style.width=s.progress+'%';}});old?.network?.dispose();s.metrics={};s.results=[];experiments.push({id,name:m.name,time:new Date().toLocaleString('zh-CN'),duration:s.fit.duration,train:s.data.train.length,val:s.data.val.length,test:s.data.test.length,origin:s.origin,metrics:null});toast(`${m.name}训练完成：${num(s.fit.duration,3)}秒`);}catch(e){s.error=e.message;toast(e.message);}finally{s.busy=false;if(page==='models'&&modelId===id)render();}}
async function evaluateRole(role){const s=current();try{if(s.busy)throw Error('训练中，请稍候');if(!s.fit)throw Error('请先训练模型');if(!s.data[role].length)throw Error('请先上传或划分'+(role==='val'?'验证':'测试')+'集');overlap(s,role);s.results=await predictModel(s.fit,s.data[role]);s.metrics[role]=evaluate(s.fit,s.results);s.role=role;s.error='';if(role==='test'){const e=experiments.findLast(e=>e.id===modelId);if(e)e.metrics=s.metrics[role];}render();toast((role==='val'?'验证':'测试')+'集计算完成');}catch(e){s.error=e.message;render();toast(e.message);}}
async function runAgent(question){const rs=scoped();answer='<div class="analysis-step"><span>✓</span>读取生产数据与规则工具，正在汇总证据…</div>';render();const text=String(question).slice(0,500),found=wells().find(w=>text.includes(w));const selected=found?data.filter(r=>r.well_id===found):rs;const grouped=Object.groupBy(selected,r=>r.well_id);let lines=[],tool='生产统计 + 规则扫描';for(const [w,a]of Object.entries(grouped)){const x=[...a].sort((a,b)=>a.date.localeCompare(b.date)),n=Math.min(30,Math.floor(x.length/2));if(!n)continue;const prev=mean(x.slice(-2*n,-n).map(r=>r.oil)),last=mean(x.slice(-n).map(r=>r.oil)),change=prev>0?100*(last-prev)/prev:null;const wa=ruleScan(x).slice(-3);lines.push(`<p><b>${esc(w)}</b>：末${n}条平均日产油 ${num(last)} 标准立方米/日，较前${n}条${change===null?'无可比基准':(change>=0?'上升':'下降')+num(Math.abs(change))+'%'}。${wa.length?'近期规则线索：'+wa.map(a=>esc(a.evidence)).join('；'):'最近未提取到规则线索。'}</p>`);}
if(/模型|效果|预测|诊断/.test(text)){const cached=Object.entries(states).filter(([id,s])=>s.fit&&s.data.test.length);for(const [id,s]of cached.slice(-2)){try{const input=found?s.data.test.filter(r=>r.well_id===found):s.data.test;if(!input.length)continue;const results=await predictModel(s.fit,input),metrics=evaluate(s.fit,results);lines.push('<p><b>'+esc(MODELS.find(m=>m.id===id).name)+' 已训练工具：</b>实际计算'+results.length+'条测试样本，'+(metrics?Object.entries(metrics).filter(([k])=>['RMSE','R2','F1','Accuracy'].includes(k)).map(([k,v])=>k+' '+fmt(v)).join('；'):'缺少标签，暂无法评价准确率')+'。来源：'+esc(s.origin??'用户上传')+'。</p>');tool+=' + '+MODELS.find(m=>m.id===id).name;}catch(e){lines.push('<p>已训练工具未执行：'+esc(e.message)+'</p>');}}if(!cached.length)lines.push('<p>当前没有已训练工具，可先在模型工作台训练；本次不报告不存在的模型指标。</p>');}
if(/预测|预判|趋势/.test(text)){try{const eligible=selected.filter(r=>r.oil>0);const fit=await trainModel('arps',eligible);const future=[];for(const [w,a]of Object.entries(grouped)){const r=[...a].sort((a,b)=>a.date.localeCompare(b.date)).at(-1);if(!fit.params[w])continue;future.push({...r,date:new Date(Date.parse(r.date)+7*864e5).toISOString().slice(0,10)});}const pred=await predictModel(fit,future);lines.push('<p><b>7日递减情景外推：</b>'+pred.map(r=>`${esc(r.well_id)}：${num(r.prediction)}标准立方米/日`).join('；')+'。使用Arps拟合的稳定递减假设，需剔除措施和停井段后再用于生产评价。</p>');tool+=' + Arps实际拟合';}catch(e){lines.push('<p>预测未执行：'+esc(e.message)+'</p>');}}
answer=`<div class="answer"><span class="tag red">任务：${esc(text)}</span><p><b>研判范围</b> · ${Object.keys(grouped).length}口井，${selected.length}条记录。</p>${lines.join('')}<p><b>建议优先级：</b>先核对零产量、开关井、计量与生产制度，再对持续产油下降和压力变化井补充试井、动液面与示功图；对含水突升井补充示踪剂和注采调整记录。现有证据不足以直接确诊水窜、堵塞或泵故障。</p><div class="source-box">工具：${tool}<br>来源：${esc(source)} · 观察截至 ${esc(selected.at(-1)?.date??'未知')}<br>结论性质：数据统计与待核实线索；未作因果确证。</div></div>`;render();}
function report(){return `# 油藏生产态势感知研判报告\n\n生成时间：${new Date().toLocaleString('zh-CN')}\n数据来源：${source}\n井范围：${well}\n记录数：${scoped().length}\n\n## 预警线索\n${alerts.filter(a=>well==='all'||a.well_id===well).slice(-30).map(a=>`- ${a.well_id} ${a.date} ${a.level}色：${a.evidence}；建议：${a.action}`).join('\n')}\n\n## 智能体研判\n${answer?answer.replace(/<[^>]+>/g,' '):'尚未执行对话任务'}\n\n## 模型实验\n${experiments.map(e=>`- ${e.name}：训练${e.train}行，耗时${e.duration.toFixed(3)}秒；测试指标${JSON.stringify(e.metrics)}；来源${e.origin}`).join('\n')}\n\n## 使用边界\n当前为历史资料回放与浏览器研究模型，规则命中不等于确诊，未自动控制生产。缺少同井同期示功图、动液面、试井/示踪剂及处置效果时，原因仅作候选。\n`;}
async function loadData(){if(!catalog.length){const c=await fetch('./data/catalog.json');if(c.ok)catalog=await c.json();}const r=await fetch('./data/volve.json');if(!r.ok)throw Error('内置数据载入失败：'+r.status);data=normalizeRows(await r.json());alerts=ruleScan(data);}
try{await loadData();render();}catch(e){root.innerHTML=`<div class="main"><h1>数据载入未完成</h1><p>${esc(e.message)}</p><button onclick="location.reload()">重新加载</button></div>`;}
